import type { SamRecordFixture } from '../../LinearAlignmentsDisplay/testUtils.ts'

// HG008-T, the Cancer Genome in a Bottle tumour, as PacBio HiFi rather than
// ONT. A second real dataset for the reconstruction, and a second cancer: the
// COLO829 fixtures next door are one melanoma line sequenced long and noisy,
// and nothing in them says whether this works on 116x HiFi against a benchmark
// callset somebody else produced.
//
// The junction is one breakend of `cluster_3`, which the V0.5 draft benchmark
// tags `EVENTTYPE=CHROMOPLEXY` and files as four breakends across chr3 and
// chr13. The two this window holds are the reciprocal pair SV_20 / SV_190,
// joining chr3:139,976,414 to chr13:114,353,244.
//
// What makes this fixture worth having is that the answer is checkable three
// ways, and the tutorial section it backs walks all three:
//
// - the CALLER says the junction is there, and says it is part of a larger
//   event, which no single junction can tell you
// - the READS say which molecule carries it, which is this file
// - the ASSEMBLY says the same thing again from no reads at all: the C-GIAB
//   T2T tumour assembly puts both loci on one contig, and named that contig
//   `chr3_chr13_hap1`. Its chr13 arm ends at 114,353,244 and its chr3 arm
//   begins at 139,976,415, abutting at one base of contig coordinate, with the
//   same orientation flip the reads describe.
//
// Records are every one carrying an SA tag over the two windows REGIONS names
// -- the windows the figure opens on, which sit INSIDE the hosted slice's own
// cut rather than matching it; `ref` is the record's own RNAME. The slice BAM
// is what the hosted demo serves, so a figure and this fixture read the same
// bytes. Regenerate with
//
//   bash scripts/gen_cgiab_read_fixture.sh
//
// which spells the query and the sort, and pastes in over the READS array.
//
// THE MATCHED NORMAL IS NOT A FIXTURE HERE, deliberately. At the same window
// it returns 51 reads and not one of them carries an SA tag, so a fixture of it
// would be 17 kB of records asserting that an empty list is empty. The control
// is real and it is checked, it is just checked by the command rather than by a
// table of CIGARs:
//
//   samtools view -F 1540 -c \
//     https://ftp-trace.ncbi.nlm.nih.gov/ReferenceSamples/giab/data_somatic/\
// HG008/Liss_lab/PacBio_Revio_20240125/\
// HG008-N-P_PacBio-HiFi-Revio_20240125_35x_GRCh38-GIABv3.bam \
//     chr3:139974000-139979000
//
// 65 of the 140 tumour reads over that same 5 kb are split; 0 of the normal's
// 51 are.

interface Rec extends SamRecordFixture {
  ref: string
}

// The windows the figure opens on. The hosted slice is cut wider than these on
// purpose, so depth and split-read support inside them are the full BAM's --
// build_demo_slices.sh says what goes wrong when it is not.
const REGIONS = [
  {
    refName: 'chr3',
    start: 139_936_789,
    end: 139_986_329,
    displayedRegionIndex: 0,
  },
  {
    refName: 'chr13',
    start: 114_317_474,
    end: 114_353_942,
    displayedRegionIndex: 1,
  },
]

// The reciprocal breakend pair the V0.5 benchmark publishes for this junction.
const SV_20 = { chr3: 139_976_414, chr13: 114_353_244 }

