function run() {
  const chains = computeReadChains(
    [
      new Map(
        REGIONS.map((region, idx) => [
          idx,
          pileupDataFromSamRecords(READS.filter(r => r.ref === region.refName)),
        ]),
      ),
    ],
    REGIONS,
  )
  return { chains, candidates: computeDerivativePaths({ chains }) }
}

// A breakend is one side of a cut and a segment edge is the last aligned base,
// so the two differ by one where the aligner agrees exactly and by a few where
// it placed the join inside a microhomology. Twenty is the clustering
// tolerance, i.e. the width at which the grouping already calls two junctions
// the same one.
function near(a: number, b: number) {
  return Math.abs(a - b) < 20
}

describe('HG008-T cluster_3, the chr3-chr13 breakend', () => {
  it('proposes the published junction as its top route, by a wide margin', () => {
    const { chains, candidates } = run()
    expect(chains).toHaveLength(145)

    const [top, next] = candidates
    expect(top!.readCount).toBe(65)
    expect(top!.segments).toHaveLength(2)
    // Six times the next route's support. The margin is the point: this window
    // sits at the chr13 q-terminus, so it is full of subtelomeric mismapping
    // (below), and a ranked list is only useful here if the real junction
    // clears that noise rather than sitting in it.
    expect(top!.readCount).toBeGreaterThan(next!.readCount * 5)
  })

  it('places both ends on the breakends the benchmark publishes', () => {
    const [top] = run().candidates
    const [first, second] = top!.segments
    // chr13 forward into the junction, then chr3 traversed backwards -- which
    // is the orientation flip the assembly contig carries too.
    expect([first!.refName, first!.strand]).toEqual(['chr13', 1])
    expect([second!.refName, second!.strand]).toEqual(['chr3', -1])
    expect(near(first!.end, SV_20.chr13)).toBe(true)
    expect(near(second!.end, SV_20.chr3)).toBe(true)
  })

  it('ranks the terminal-repeat mismapping below it rather than filtering it out', () => {
    // This window ends at the chr13 q-terminus, so it is full of reads whose
    // other end lands in some other chromosome's terminal repeat -- chr1 and
    // chr12 at their starts, chr5 near its end, an unplaced contig. Each is a
    // confident-looking two-segment route, which is exactly the failure the
    // picker's caveat warns about and cannot itself detect.
    //
    // Their presence is what makes this dataset a better test than a clean one.
    // The feature has to rank the real junction above them without being told
    // which is which, and it must not drop them either: a window producing this
    // many routes is saying something about all of them.
    const runnersUp = run().candidates.slice(1)
    expect(runnersUp.length).toBeGreaterThan(3)
    for (const candidate of runnersUp) {
      // None of them lands on the published breakend pair. That is the whole
      // difference: the somatic junction is the one route whose ends are where
      // the caller and the assembly independently put them.
      const onTheCall = candidate.segments.some(
        seg => near(seg.end, SV_20.chr3) || near(seg.end, SV_20.chr13),
      )
      expect(onTheCall).toBe(false)

      // And the ones that reach the junction say so structurally too. The real
      // route STOPS there; a mismapped read carries straight on, out into the
      // terminal repeat the reference still has and this allele does not.
      //
      // Scoped to the routes that get there at all, because not every one does:
      // the chr13 arm also collects reads whose other end is some OTHER
      // chromosome's terminus (chr4's, ~115 kb short of it), and those sit well
      // below the junction on chr13 and never approach it. Asserting this over
      // every runner-up passed only while the demo slice was cut too narrow to
      // contain them -- see scripts/build_demo_slices.sh.
      const reachesTheJunction = candidate.segments.some(
        seg => seg.refName === 'chr13' && seg.end > SV_20.chr13 - 500,
      )
      if (reachesTheJunction) {
        const runsPastIt = candidate.segments.some(
          seg => seg.refName === 'chr13' && seg.end > SV_20.chr13 + 500,
        )
        expect(runsPastIt).toBe(true)
      }
    }
  })
})
